def mode_to_text(mode):
    if not isinstance(mode, int):
        raise ValueError("Mode must be an integer")
    if isinstance(mode, bool):
        raise ValueError("Boolean values are not accepted as mode")
    if not (0 <= mode <= 0o7777):
        raise ValueError("Mode out of range (0-0o7777)")

    result = []

    # Owner triplet
    r = (mode & 0o400) != 0
    w = (mode & 0o200) != 0
    x = (mode & 0o100) != 0
    special = (mode & 0o4000) != 0
    if special:
        third = 's' if x else 'S'
    else:
        third = 'x' if x else '-'
    result.extend(['r' if r else '-', 'w' if w else '-', third])

    # Group triplet
    r = (mode & 0o040) != 0
    w = (mode & 0o020) != 0
    x = (mode & 0o010) != 0
    special = (mode & 0o2000) != 0
    if special:
        third = 's' if x else 'S'
    else:
        third = 'x' if x else '-'
    result.extend(['r' if r else '-', 'w' if w else '-', third])

    # Others triplet
    r = (mode & 0o004) != 0
    w = (mode & 0o002) != 0
    x = (mode & 0o001) != 0
    special = (mode & 0o1000) != 0
    if special:
        third = 't' if x else 'T'
    else:
        third = 'x' if x else '-'
    result.extend(['r' if r else '-', 'w' if w else '-', third])

    return ''.join(result)

def text_to_mode(text):
    if not isinstance(text, str) or len(text) != 9:
        raise ValueError("Text must be a 9-character string")

    # Validate each character
    for i in (0, 3, 6):
        if text[i] not in ('r', '-'):
            raise ValueError(f"Invalid character at position {i}: {text[i]}")
    for i in (1, 4, 7):
        if text[i] not in ('w', '-'):
            raise ValueError(f"Invalid character at position {i}: {text[i]}")
    if text[2] not in ('x', '-', 's', 'S'):
        raise ValueError(f"Invalid character at position 2: {text[2]}")
    if text[5] not in ('x', '-', 's', 'S'):
        raise ValueError(f"Invalid character at position 5: {text[5]}")
    if text[8] not in ('x', '-', 't', 'T'):
        raise ValueError(f"Invalid character at position 8: {text[8]}")

    mode = 0
    # Masks for each triplet (r, w, x, special)
    triplets = [
        (0o400, 0o200, 0o100, 0o4000),  # owner
        (0o040, 0o020, 0o010, 0o2000),  # group
        (0o004, 0o002, 0o001, 0o1000),  # others
    ]
    # Positions for each triplet
    positions = [
        (0, 1, 2),  # owner
        (3, 4, 5),  # group
        (6, 7, 8),  # others
    ]

    for (r_pos, w_pos, t_pos), (r_mask, w_mask, x_mask, s_mask) in zip(positions, triplets):
        # Add r and w bits
        if text[r_pos] == 'r':
            mode += r_mask
        if text[w_pos] == 'w':
            mode += w_mask

        t_char = text[t_pos]
        if t_char == 'x':
            mode += x_mask
        elif t_char in ('s', 'S', 't', 'T'):
            if t_char in ('s', 't'):
                mode += x_mask
            mode += s_mask

    return mode

def format_size(n):
    unit_exponents = [None, 'KiB', 'MiB', 'GiB', 'TiB', 'PiB']
    if not isinstance(n, int) or isinstance(n, bool):
        raise ValueError("n must be a non-negative integer")
    if n < 0:
        raise ValueError("n must be a non-negative integer")
    if n < 1024:
        return f"{n} B"
    # Find the largest exponent
    exp = 0
    for e in [5, 4, 3, 2, 1]:
        if 1024 ** e <= n:
            exp = e
            break
    divisor = 1024 ** exp
    tenths = 10 * n
    q, r = divmod(tenths, divisor)
    divisor_half = divisor // 2
    rounded_tenths = q + (1 if r >= divisor_half else 0)
    # Check if we need to adjust the exponent
    if rounded_tenths == 10240 and exp < 5:
        exp += 1
        rounded_tenths = 10
    unit = unit_exponents[exp]
    return f"{rounded_tenths / 10:.1f} {unit}"

def parse_size(text):
    unit_exponents = {'B': 0, 'KiB': 1, 'MiB': 2, 'GiB': 3, 'TiB': 4, 'PiB': 5}
    parts = text.split()
    if len(parts) != 2:
        raise ValueError("Invalid format")
    number_part, unit_part = parts
    if text != f"{number_part} {unit_part}":
        raise ValueError("Invalid format")
    if unit_part not in unit_exponents:
        raise ValueError("Invalid unit")
    unit_exp = unit_exponents[unit_part]
    unit_value = 1024 ** unit_exp
    # Validate number part
    if unit_part == 'B':
        if '.' in number_part:
            raise ValueError("Invalid number for B unit")
        try:
            num = int(number_part)
        except ValueError:
            raise ValueError("Invalid number for B unit")
        return num
    else:
        if '.' in number_part:
            integer_part, fractional_part = number_part.split('.')
        else:
            integer_part, fractional_part = number_part, ''
        if not integer_part or not fractional_part:
            raise ValueError("Invalid number format")
        decimal_length = len(fractional_part)
        try:
            integer_val = int(integer_part)
            fractional_val = int(fractional_part)
        except ValueError:
            raise ValueError("Invalid number format")
        numerator = integer_val * (10 ** decimal_length) + fractional_val
        denominator = 10 ** decimal_length
        total = numerator * unit_value
        q, r = divmod(total, denominator)
        if 2 * r > denominator or 2 * r == denominator:
            return q + 1
        else:
            return q

