        (1024**2, 'MiB'),
        (1024**1, 'KiB'),
    ]
    for i in range(len(units)):
        divisor, unit = units[i]
        if n >= divisor:
            initial_i = i
            initial_divisor = divisor
            initial_unit = unit
            break
    total = 10 * n
    quotient, remainder = divmod(total, initial_divisor)
    if remainder * 2 >= initial_divisor:
        rounded_total = quotient + 1
    else:
        rounded_total = quotient
    if rounded_total >= 10240 and initial_i > 0:
        new_divisor, new_unit = units[initial_i - 1]
        new_total = 10 * n
        new_quotient, new_remainder = divmod(new_total, new_divisor)
        if new_remainder * 2 >= new_divisor:
            new_rounded_total = new_quotient + 1
        else:
            new_rounded_total = new_quotient
        rounded_total = new_rounded_total
        initial_unit = new_unit
    integer_part = rounded_total // 10
    decimal_digit = rounded_total % 10
    return f"{integer_part}.{decimal_digit} {initial_unit}"

