def expand_tabs(line, width):
    if not isinstance(line, str) or '\n' in line or '\r' in line:
        raise ValueError
    if not (type(width) is int and 1 <= width <= 32):
        raise ValueError
    current_column = 0
    output = []
    for char in line:
        if char == '\t':
            next_stop = ((current_column // width) + 1) * width
            spaces_needed = next_stop - current_column
            output.append(' ' * spaces_needed)
            current_column = next_stop
        else:
            output.append(char)
            current_column += 1
    return ''.join(output)

