def qp_encode(data):
    if not isinstance(data, (bytes, bytearray)):
        raise ValueError
    tokens = []
    n = len(data)
    for i in range(n):
        byte = data[i]
        if 33 <= byte <= 126 and byte != 61:  # Not '='
            tokens.append(chr(byte))
        else:
            if byte == 32 and i < n - 1:
                tokens.append(' ')
            else:
                tokens.append(f'={byte:02X}')
    output = []
    current_line = ''
    for i in range(len(tokens)):
        token = tokens[i]
        is_last_token = (i == len(tokens) - 1)
        token_len = len(token)
        max_allowed = 75 if not is_last_token else 76
        if len(current_line) + token_len <= max_allowed:
            current_line += token
        else:
            output.append(current_line)
            output.append('=\r\n')
            current_line = token
    output.append(current_line)
    return ''.join(output)

def qp_decode(text):
    if not isinstance(text, str):
        raise ValueError
    text = text.replace('=\r\n', '')
    i = 0
    result = []
    while i < len(text):
        c = text[i]
        if c == '=':
            if i + 2 >= len(text):
                raise ValueError
            hex_part = text[i+1:i+3]
            try:
                byte = int(hex_part, 16)
            except ValueError:
                raise ValueError
            result.append(byte)
            i += 3
        else:
            ord_c = ord(c)
            if ord_c > 127 or ord_c < 32:
                raise ValueError
            if ord_c in (13, 10):
                raise ValueError
            result.append(ord_c)
            i += 1
    return bytes(result)

