import re

def parse_params(value):
    value = value.strip()
    if not value:
        raise ValueError("Empty value")

    semicolon_pos = value.find(';')
    if semicolon_pos == -1:
        mediatype_part = value
        params_part = ''
    else:
        mediatype_part = value[:semicolon_pos].rstrip()
        params_part = value[semicolon_pos:].lstrip()

    mediatype_tokens = mediatype_part.split('/', 1)
    if len(mediatype_tokens) != 2 or not all(is_token(t) for t in mediatype_tokens):
        raise ValueError("Invalid mediatype")
    mediatype = f"{mediatype_tokens[0].lower()}/{mediatype_tokens[1].lower()}"

    params = {}
    for part in params_part.split(';'):
        part_stripped = part.strip()
        if not part_stripped:
            continue
        if '=' not in part_stripped:
            raise ValueError("Parameter without value")
        name, value = part_stripped.split('=', 1)
        if not name or not value:
            raise ValueError("Empty parameter name or value")
        if not is_token(name):
            raise ValueError("Invalid parameter name")
        lower_name = name.lower()
        if lower_name in params:
            raise ValueError("Duplicate parameter name")
        if value.startswith('"'):
            try:
                parsed_value = parse_quoted_string(value)
            except ValueError:
                raise ValueError("Invalid quoted string")
        elif not is_token(value):
            raise ValueError("Invalid parameter value")
        else:
            parsed_value = value
        params[lower_name] = parsed_value
    return (mediatype, params)

def format_params(mediatype, params):
    if not re.fullmatch(r'[^/]+/[^/]+', mediatype):
        raise ValueError("Invalid mediatype")
    if not isinstance(params, dict):
        raise ValueError("Params must be a dict")
    formatted_params = []
    lower_keys = set()
    for key in sorted(params.keys(), key=lambda s: s.lower()):
        lower_key = key.lower()
        if lower_key in lower_keys:
            raise ValueError("Duplicate parameter name")
        lower_keys.add(lower_key)
        value = params[key]
        if not is_token(key):
            raise ValueError("Invalid parameter key")
        if not isinstance(value, str):
            raise ValueError("Parameter value must be a string")
        if any(ord(c) < 32 or ord(c) == 127 for c in value):
            raise ValueError("Control character in parameter value")
        if is_token(value):
            formatted_params.append(f"{lower_key}={value}")
        else:
            escaped_value = value.replace('\\', '\\\\').replace('"', '\\"')
            formatted_params.append(f'{lower_key}="{escaped_value}"')
    return mediatype.lower() + ('; ' + '; '.join(formatted_params) if formatted_params else '')

def is_token(s):
    return bool(re.fullmatch(r'[-a-zA-Z0-9!#$%&\'*+.^_`|~]+', s))

def parse_quoted_string(s):
    if not s.startswith('"') or not s.endswith('"'):
        raise ValueError
    s_content = s[1:-1]
    i = 0
    result = []
    while i < len(s_content):
        if s_content[i] == '\\':
            if i + 1 >= len(s_content):
                raise ValueError
            next_char = s_content[i+1]
            if ord(next_char) < 32 or ord(next_char) == 127:
                raise ValueError
            result.append(next_char)
            i += 2
        else:
            c = s_content[i]
            if ord(c) < 32 or ord(c) == 127:
                raise ValueError
            result.append(c)
            i += 1
    return ''.join(result)

