    if not isinstance(tree, dict):
        raise ValueError("Input must be a dict")
    result = {}
    def _flatten(current, path):
        if not current:
            if path:
                result[path] = {}
            return
        for key in current:
            if not isinstance(key, str) or key == '' or '.' in key:
                raise ValueError(f"Invalid key: {key}")
            new_path = path + (key if not path else path + '.' + key)
            value = current[key]
            if isinstance(value, dict):
                if not value:
                    result[new_path] = {}
                else:
                    _flatten(value, new_path)
            else:
                result[new_path] = value
    _flatten(tree, '')
    return result

