    def parse_heading(line):
        level = 0
        for c in line:
            if c == '#':
                level += 1
            else:
                break
        if level == 0 or level > 6:
            return None
        if len(line) <= level or line[level] != ' ':
            return None
        title = line[level+1:]
        if not title or title[0] == ' ' or title[-1] == ' ' or '\n' in title:
            return None
        return (level, title)

    parsed = []
    for line in lines:
        res = parse_heading(line)
        if res is None:
            raise ValueError("Invalid heading line")
        parsed.append(res)

    if not parsed:
        return []

    if parsed[0][0] != 1:
        raise ValueError("First heading is not level 1")

    result = []
    prev_level, prev_title = parsed[0]
    current_outline = [1]
    result.append(f"1 {prev_title}")

    for i in range(1, len(parsed)):
        level, title = parsed[i]
        prev_level_prev = prev_level
        if level > prev_level_prev + 1:
            raise ValueError("Invalid level increase")

        if level > prev_level_prev:
            new_outline = current_outline + [1]
        elif level == prev_level_prev:
            new_outline = current_outline[:-1] + [current_outline[-1] + 1]
        else:
            truncated = current_outline[:level]
            truncated[-1] += 1
            new_outline = truncated

        current_outline = new_outline
        outline_str = '.'.join(map(str, current_outline))
        result.append(f"{outline_str} {title}")
        prev_level = level

    return result

