        prev_outline = current_outline
        len_prev = len(prev_outline)
        len_new = len(numbers)

        if len_new > len_prev + 1:
            raise ValueError("Invalid sequence")

        valid = False
        if len_new == len_prev + 1:
            expected = prev_outline + [1]
            valid = (numbers == expected)
        elif len_new == len_prev:
            expected = prev_outline[:-1] + [prev_outline[-1] + 1]
            valid = (numbers == expected)
        else:
