def zeckendorf(n):
    if type(n) is not int or not (0 <= n <= 10**30):
        raise ValueError
    if n == 0:
        return []
    fibs = []
    a, b = 1, 2
    while a <= n:
        fibs.append(a)
        a, b = b, a + b
    result = []
    remaining = n
    i = len(fibs) - 1
    while remaining > 0:
        if i < 0:
            break
        current = fibs[i]
        if current <= remaining:
            result.append(current)
            remaining -= current
            i -= 2
        else:
            i -= 1
    return result

