import math

def aliquot_chain(n, limit):
    if type(n) is not int or type(limit) is not int:
        raise ValueError
    if not (1 <= n <= 10**6) or not (1 <= limit <= 1000):
        raise ValueError

    def sum_proper(m):
        if m == 1:
            return 0
        total = 1
        sqrt_m = int(math.sqrt(m))
        for i in range(2, sqrt_m + 1):
            if m % i == 0:
                other = m // i
                if i == other:
                    total += i
                else:
                    total += i + other
        return total

    terms = [n]
    for _ in range(limit):
        last = terms[-1]
        s = sum_proper(last)
        if s == 0:
            terms.append(0)
            return ('terminates', terms)
        if s in terms:
            idx = terms.index(s)
            cycle_length = len(terms) - idx
            if idx == 0:
                if cycle_length == 1:
                    kind = 'perfect'
                elif cycle_length == 2:
                    kind = 'amicable'
                else:
                    kind = 'sociable'
            else:
                if cycle_length == 1:
                    kind = 'aspiring'
                else:
                    kind = 'cyclic'
            return (kind, terms)
        else:
            terms.append(s)
            if s > 10**9:
                return ('unknown', terms)
    return ('unknown', terms)

import math

def is_prime_power(m):
    if m == 1:
        return False
    original_m = m
    factors = set()
    if m % 2 == 0:
        factors.add(2)
        while m % 2 == 0:
            m //= 2
    i = 3
    while i * i <= m:
        if m % i == 0:
            factors.add(i)
            while m % i == 0:
                m //= i
        i += 2
    if m > 1:
        factors.add(m)
    return len(factors) == 1

def has_primitive_roots(n):
    if n == 2 or n == 4:
        return True
    if n % 2 == 1:
        return is_prime_power(n)
    else:
        m = n // 2
        if m % 2 == 1:
            return is_prime_power(m)
        else:
            return False

def euler_phi(n):
    result = n
    if n % 2 == 0:
        result = result // 2
        while n % 2 == 0:
            n //= 2
    i = 3
    while i * i <= n:
        if n % i == 0:
            while n % i == 0:
                n //= i
            result = result // i * (i - 1)
        i += 2
    if n > 1:
        result = result // n * (n - 1)
    return result

def get_prime_factors(m):
    if m == 1:
        return set()
    factors = set()
    if m % 2 == 0:
        factors.add(2)
        while m % 2 == 0:
            m //= 2
    i = 3
    while i <= 10**5 and i * i <= m:
        if m % i == 0:
            factors.add(i)
            while m % i == 0:
                m //= i
        i += 2
    if m > 1:
        factors.add(m)
    return factors

def smallest_primitive_root(n):
    if not (isinstance(n, int) and 2 <= n <= 10**10):
        raise ValueError()
    if not has_primitive_roots(n):
        return None
    phi_n = euler_phi(n)
    q_primes = get_prime_factors(phi_n)
    for g in range(1, n):
        if math.gcd(g, n) != 1:
            continue
        is_root = True
        for q in q_primes:
            if pow(g, phi_n // q, n) == 1:
                is_root = False
                break
        if is_root:
            return g
    return None

def count_primitive_roots(n):
    if not (isinstance(n, int) and 2 <= n <= 10**10):
        raise ValueError()
    if not has_primitive_roots(n):
        return 0
    phi_n = euler_phi(n)
    phi_phi_n = euler_phi(phi_n)
    return phi_phi_n

def factorize(b):
    factors = []
    count = 0
    while b % 2 == 0:
        count += 1
        b = b // 2
    if count > 0:
        factors.append((2, count))
    i = 3
    while i * i <= b:
        count_i = 0
        while b % i == 0:
            count_i += 1
            b = b // i
        if count_i > 0:
            factors.append((i, count_i))
        i += 2
    if b > 1:
        factors.append((b, 1))
    return factors

def legendre(n, p):
    count = 0
    power = p
    while power <= n:
        count += n // power
        power *= p
    return count

def trailing_zeros(n, b):
    if type(n) is not int:
        raise ValueError("n must be an integer")
    if not (0 <= n <= 10**18):
        raise ValueError("n must be between 0 and 1e18")
    if type(b) is not int:
        raise ValueError("b must be an integer")
    if not (2 <= b <= 10**6):
        raise ValueError("b must be between 2 and 1e6")
    factors = factorize(b)
    min_z = float('inf')
    for (p, e) in factors:
        v = legendre(n, p)
        current_z = v // e
        if current_z < min_z:
            min_z = current_z
    return min_z

def binomial_zeros(n, k, b):
    if type(n) is not int:
        raise ValueError("n must be an integer")
    if not (0 <= n <= 10**18):
        raise ValueError("n must be between 0 and 1e18")
    if type(k) is not int:
        raise ValueError("k must be an integer")
    if not (0 <= k <= n):
        raise ValueError("k must be between 0 and n")
    if type(b) is not int:
        raise ValueError("b must be an integer")
    if not (2 <= b <= 10**6):
        raise ValueError("b must be between 2 and 1e6")
    factors = factorize(b)
    min_z = float('inf')
    for (p, e) in factors:
        v_n = legendre(n, p)
        v_k = legendre(k, p)
        v_nk = legendre(n - k, p)
        v = v_n - v_k - v_nk
        current_z = v // e
        if current_z < min_z:
            min_z = current_z
    return min_z

def lucky_numbers(limit):
    if not isinstance(limit, int) or isinstance(limit, bool):
        raise ValueError
    if limit < 0 or limit > 10**5:
        raise ValueError
    if limit < 1:
        return []
    current_list = list(range(1, limit + 1, 2))
    current_step_index = 1
    while current_step_index < len(current_list):
        m = current_list[current_step_index]
        new_list = []
        count = 1
        for element in current_list:
            if count == m:
                count = 1
            else:
                new_list.append(element)
                count += 1
        current_list = new_list
        current_step_index += 1
    return current_list

