def gauss_divmod(a, b):
    # Validate inputs
    for arg in [a, b]:
        if not (isinstance(arg, (tuple, list)) and len(arg) == 2):
            raise ValueError
        x, y = arg
        if type(x) is not int or type(y) is not int:
            raise ValueError
        if abs(x) > 10**18 or abs(y) > 10**18:
            raise ValueError
    if b[0] == 0 and b[1] == 0:
        raise ValueError

    x1, y1 = a
    x2, y2 = b
    den = x2 * x2 + y2 * y2
    u_num = x1 * x2 + y1 * y2
    v_num = y1 * x2 - x1 * y2

    q_real = (u_num + den // 2) // den
    q_imag = (v_num + den // 2) // den

    # Compute q * b
    q_x, q_y = q_real, q_imag
    b_x, b_y = x2, y2
    product_real = q_x * b_x - q_y * b_y
    product_imag = q_x * b_y + q_y * b_x

    # Compute remainder
    r_real = x1 - product_real
    r_imag = y1 - product_imag

    return (q_real, q_imag), (r_real, r_imag)


