        if parent[i] == -1:
            root_count += 1
            root = i
    if root_count != 1:
        raise ValueError
    for v in range(n):
        if v == root:
            continue
        p = parent[v]
        if p < 0 or p >= n or p == v:
            raise ValueError
    children = [[] for _ in range(n)]
    for v in range(n):
        if v != root:
            children[parent[v]].append(v)
    visited = set()
    stack = [root]
    while stack:
        node = stack.pop()
        if node in visited:
            continue
        visited.add(node)
        for child in children[node]:
            stack.append(child)
    if len(visited) != n:
        raise ValueError
    if not isinstance(queries, list):
        raise ValueError
    for q in queries:
        if len(q) != 2:
            raise ValueError
        u, v = q
        if not (isinstance(u, int) and isinstance(v, int)) or isinstance(u, bool) or isinstance(v, bool):
            raise ValueError
        if u < 0 or u >= n or v < 0 or v >= n:
            raise ValueError
    depth = [0] * n
    from collections import deque
    queue = deque([root])
    while queue:
        node = queue.popleft()
        for child in children[node]:
            depth[child] = depth[node] + 1
            queue.append(child)
