        for v in range(n):
            if binary_lift[k-1][v] != -1:
                binary_lift[k][v] = binary_lift[k-1][binary_lift[k-1][v]]
            else:
                binary_lift[k][v] = -1
    answers = []
    for u, v in queries:
        if depth[u] < depth[v]:
            u, v = v, u
        for k in reversed(range(log_max)):
            if depth[u] - (1 << k) >= depth[v]:
                u = binary_lift[k][u]
        if u == v:
            lca_node = u
