def maze_steps(grid):
    # Validate grid structure
    if not grid:
        raise ValueError
    height = len(grid)
    if not (1 <= height <= 30):
        raise ValueError
    width = len(grid[0])
    if not (1 <= width <= 30):
        raise ValueError
    for row in grid:
        if len(row) != width:
            raise ValueError

    # Validate content and find S, E
    s_count = e_count = 0
    start = end = None
    for i in range(height):
        for j in range(width):
            c = grid[i][j]
            if c == 'S':
                s_count += 1
                start = (i, j)
            elif c == 'E':
                e_count += 1
                end = (i, j)
            else:
                if c not in {'#', '.', 'a', 'b', 'c', 'd', 'A', 'B', 'C', 'D'}:
                    raise ValueError
    if s_count != 1 or e_count != 1:
        raise ValueError

    # BFS setup
    from collections import deque
    queue = deque()
    queue.append((start[0], start[1], 0, 0))
    visited = set()
    visited.add((start[0], start[1], 0))
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    while queue:
        row, col, mask, steps = queue.popleft()

        for dr, dc in directions:
            new_row, new_col = row + dr, col + dc
            if 0 <= new_row < height and 0 <= new_col < width:
                cell = grid[new_row][new_col]

                if cell == '#':
                    continue

                # Check doors
                if 'A' <= cell <= 'D':
                    key_idx = ord(cell.lower()) - ord('a')
                    if not (mask & (1 << key_idx)):
