                # Update mask if key is collected
                new_mask = mask
                if 'a' <= cell <= 'd':
                    key_idx = ord(cell) - ord('a')
                    new_mask = mask | (1 << key_idx)

                state = (new_row, new_col, new_mask)
                if state not in visited:
                    visited.add(state)
                    queue.append((new_row, new_col, new_mask, steps + 1))

    return -1

