import re

class DSU:
    def __init__(self):
        self.parent = {}
        self.rank = {}

    def add(self, x):
        if x not in self.parent:
            self.parent[x] = x
            self.rank[x] = 0

    def find(self, x):
        if self.parent[x] != x:
            self.parent[x] = self.find(self.parent[x])
        return self.parent[x]

    def union(self, x, y):
        x_root = self.find(x)
        y_root = self.find(y)
        if x_root == y_root:
            return
        if self.rank[x_root] < self.rank[y_root]:
            self.parent[x_root] = y_root
        else:
            self.parent[y_root] = x_root
            if self.rank[x_root] == self.rank[y_root]:
                self.rank[x_root] += 1

def validate_constraints(constraints):
    if not isinstance(constraints, list):
        raise ValueError
    eq_regex = r'^[a-z][a-z0-9]{0,7}==[a-z][a-z0-9]{0,7}$'
    neq_regex = r'^[a-z][a-z0-9]{0,7}![=][a-z][a-z0-9]{0,7}$'
    for c in constraints:
        if not isinstance(c, str):
            raise ValueError
        if re.fullmatch(eq_regex, c) is None and re.fullmatch(neq_regex, c) is None:
            raise ValueError

def satisfiable(constraints):
    validate_constraints(constraints)
    equality = []
    disequality = []
    variables = set()
    for c in constraints:
        if '==' in c:
            x, y = c.split('==')
            equality.append((x, y))
        else:
            x, y = c.split('!=')
            disequality.append((x, y))
        variables.add(x)
        variables.add(y)
    if not variables:
        return True
    dsu = DSU()
    for var in variables:
        dsu.add(var)
    for x, y in equality:
        dsu.union(x, y)
    for x, y in disequality:
        if dsu.find(x) == dsu.find(y):
            return False
    return True

def eq_classes(constraints):
    validate_constraints(constraints)
    if not satisfiable(constraints):
        return None
    equality = []
    variables = set()
    for c in constraints:
        if '==' in c:
            x, y = c.split('==')
            equality.append((x, y))
        variables.add(c.split('==')[0] if '==' in c else c.split('!=')[0])
        variables.add(c.split('==')[1] if '==' in c else c.split('!=')[1])
    if not variables:
        return []
    dsu = DSU()
    for var in variables:
        dsu.add(var)
    for x, y in equality:
        dsu.union(x, y)
    groups = {}
    for var in variables:
        root = dsu.find(var)
        if root not in groups:
            groups[root] = []
        groups[root].append(var)
    result = []
    for group in groups.values():
        result.append(sorted(group))
    result.sort()
    return result

def rho_shapes(f):
    n = len(f)
    if n == 0:
        raise ValueError
    if not isinstance(f, list):
        raise ValueError
    for x in f:
        if type(x) is not int:
            raise ValueError
        if not (0 <= x < n):
            raise ValueError

    tail = [0] * n
    cycle_len = [0] * n
    visited = [False] * n

    for start in range(n):
        if not visited[start]:
            path = []
            node_index = {}
            current = start
            while True:
                path.append(current)
                node_index[current] = len(path) - 1
                next_node = f[current]
                if next_node in node_index:
                    # Found a cycle
                    cycle_start = node_index[next_node]
                    cycle_length = len(path) - cycle_start
                    for i in range(cycle_start, len(path)):
                        node = path[i]
                        tail[node] = 0
                        cycle_len[node] = cycle_length
                        visited[node] = True
                    for i in range(cycle_start):
                        node = path[i]
                        tail[node] = cycle_start - i
                        cycle_len[node] = cycle_length
                        visited[node] = True
                    break
                elif visited[next_node]:
                    # next_node is already processed
                    t = tail[next_node]
                    cl = cycle_len[next_node]
                    path_len = len(path)
                    for i in range(path_len):
                        node = path[i]
                        tail[node] = (path_len - i) + t
                        cycle_len[node] = cl
                        visited[node] = True
                    break
                else:
                    current = next_node
    return list(zip(tail, cycle_len))

