def line_cells(x0, y0, x1, y1):
    if any(type(arg) is not int for arg in (x0, y0, x1, y1)):
        raise ValueError
    for arg in (x0, y0, x1, y1):
        if abs(arg) > 10**6:
            raise ValueError
    dx = x1 - x0
    dy = y1 - y0
    if abs(dx) >= abs(dy):
        if dx == 0:
            return [(x0, y0)]
        dx_abs = abs(dx)
        sx = 1 if dx > 0 else -1
        points = []
        for i in range(dx_abs + 1):
            x = x0 + i * sx
            numerator = i * dy
            q, rem = divmod(numerator, dx_abs)
            if 2 * rem == dx_abs:
                if dy >= 0:
                    r_i = q + 1
                else:
                    r_i = q - 1
            else:
                r_i = (numerator + (dx_abs // 2)) // dx_abs
            y = y0 + r_i
            points.append((x, y))
        return points
    else:
        if dy == 0:
            return [(x0, y0)]
        dy_abs = abs(dy)
        sy = 1 if dy > 0 else -1
        points = []
        for i in range(dy_abs + 1):
            y = y0 + i * sy
            numerator = i * dx
            q, rem = divmod(numerator, dy_abs)
            if 2 * rem == dy_abs:
                if dx >= 0:
                    r_i = q + 1
                else:
                    r_i = q - 1
            else:
                r_i = (numerator + (dy_abs // 2)) // dy_abs
            x = x0 + r_i
            points.append((x, y))
        return points

