    ax, ay = a
    bx, by = b
    if not (0 <= ax < len(grid[0]) and 0 <= ay < len(grid) and 0 <= bx < len(grid[0]) and 0 <= by < len(grid)):
        raise ValueError
    cells = line_cells(ax, ay, bx, by)
    a_cell = cells[0]
    b_cell = cells[-1]
    for cell in cells:
        x, y = cell
        if not (0 <= x < len(grid[0]) and 0 <= y < len(grid)):
            continue  # out of bounds, not considered as blocking
        if (x, y) == a_cell or (x, y) == b_cell:
            continue
        if grid[y][x] == '#':
            return False
    return True

