    others = [tuple(p) for p in points if not (p[0] == ox and p[1] == oy)]

    def compare(a, b):
        ax, ay = a
        bx, by = b
        dx1 = ax - ox
        dy1 = ay - oy
        dx2 = bx - ox
        dy2 = by - oy
        cross = dx1 * dy2 - dy1 * dx2
        if cross > 0:
            return -1
        elif cross < 0:
            return 1
        else:
            dist1_sq = dx1**2 + dy1**2
            dist2_sq = dx2**2 + dy2**2
            if dist1_sq < dist2_sq:
                return -1
            elif dist1_sq > dist2_sq:
                return 1
            else:
                return 0

