        if type(x) is not int or type(y) is not int:
            raise ValueError
        if abs(x) > 10**6 or abs(y) > 10**6:
            raise ValueError

    directions = set()
    for p in points:
        x, y = p
        if x == ox and y == oy:
            continue
        dx = x - ox
        dy = y - oy
        if dx == 0 and dy == 0:
            continue
        g = math.gcd(abs(dx), abs(dy))
        a = dx // g
        b = dy // g
        if a == 0:
            if b < 0:
                b = -b
        else:
            if a < 0:
                a = -a
                b = -b
        directions.add((a, b))
    return len(directions)

