    if not (isinstance(eggs, int) and 1 <= eggs <= 64):
        raise ValueError
    if not (isinstance(floors, int) and 0 <= floors <= 10**18):
        raise ValueError
    if floors == 0:
        return 0
    if eggs == 1:
        return floors
    low = 1
    high = 1
    while compute_sum(high, eggs, floors) < floors:
        high *= 2
    while low < high:
        mid = (low + high) // 2
        if compute_sum(mid, eggs, floors) >= floors:
            high = mid
        else:
            low = mid + 1
    return low

