def interleave_count(a, b, c):
    if not (isinstance(a, str) and isinstance(b, str) and isinstance(c, str)):
        raise ValueError
    if len(a) > 300 or len(b) > 300:
        raise ValueError
    m, n = len(a), len(b)
    if len(c) != m + n:
        return 0
    dp = [[0] * (n + 1) for _ in range(m + 1)]
    dp[0][0] = 1
    for i in range(m + 1):
        for j in range(n + 1):
            if i == 0 and j == 0:
                continue
            current_pos = i + j - 1
            val = 0
            if i > 0 and a[i - 1] == c[current_pos]:
                val += dp[i - 1][j]
            if j > 0 and b[j - 1] == c[current_pos]:
                val += dp[i][j - 1]
            dp[i][j] = val
    return dp[m][n]


def interleave_labels(a, b, c):
    if not (isinstance(a, str) and isinstance(b, str) and isinstance(c, str)):
        raise ValueError
    if len(a) > 300 or len(b) > 300:
        raise ValueError
    m, n = len(a), len(b)
    if len(c) != m + n:
        return None
    reachable = [[False] * (n + 1) for _ in range(m + 1)]
    for i in range(m, -1, -1):
        for j in range(n, -1, -1):
            if i == m and j == n:
                reachable[i][j] = True
            else:
                current_pos = i + j
                option_a = False
                if i < m and a[i] == c[current_pos] and reachable[i + 1][j]:
                    option_a = True
                option_b = False
                if j < n and b[j] == c[current_pos] and reachable[i][j + 1]:
                    option_b = True
                reachable[i][j] = option_a or option_b
    if not reachable[0][0]:
        return None
    label = []
    i, j = 0, 0
    while i < m or j < n:
        current_pos = i + j
        if i < m and a[i] == c[current_pos] and reachable[i + 1][j]:
            label.append('A')
            i += 1
        else:
            label.append('B')
            j += 1
    return ''.join(label)

