def topple(grid):
    # Validate grid structure
    if not isinstance(grid, list) or not grid:
        raise ValueError()
    rows = len(grid)
    cols = len(grid[0])
    if cols == 0:
        raise ValueError()
    for row in grid:
        if not isinstance(row, list) or len(row) != cols:
            raise ValueError()
        for cell in row:
            if type(cell) is not int:
                raise ValueError()
            if not (0 <= cell <= 10000):
                raise ValueError()

    # Create a deep copy of the grid
    grid_copy = [row.copy() for row in grid]
    queue = deque()

    # Initialize queue with unstable cells
    for i in range(rows):
        for j in range(cols):
            if grid_copy[i][j] >= 4:
                queue.append((i, j))

    count = 0

    # Process the queue
    while queue:
        i, j = queue.popleft()
        current = grid_copy[i][j]
        k = current // 4
        if k == 0:
            continue
        count += k
        grid_copy[i][j] -= 4 * k

        # Distribute grains to neighbors
        directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
        for dx, dy in directions:
            ni = i + dx
            nj = j + dy
            if 0 <= ni < rows and 0 <= nj < cols:
                grid_copy[ni][nj] += k
                if grid_copy[ni][nj] >= 4:
                    queue.append((ni, nj))

    return (grid_copy, count)

