def play_snake(height, width, food, moves):
    # Validate height and width
    if not (1 <= height <= 50) or not (1 <= width <= 50):
        raise ValueError("Height and width must be between 1 and 50 inclusive.")

    # Validate food
    for f in food:
        if not (isinstance(f, (tuple, list)) and len(f) == 2):
            raise ValueError("Each food item must be a tuple or list of two integers.")
        row, col = f
        if not isinstance(row, int) or not isinstance(col, int):
            raise ValueError("Food coordinates must be integers.")
        if not (0 <= row < height) or not (0 <= col < width):
            raise ValueError("Food coordinates are out of bounds.")

    # Validate moves
    for move in moves:
        if move not in {'U', 'D', 'L', 'R'}:
            raise ValueError("Moves must consist of 'U', 'D', 'L', or 'R'.")

    snake = deque([(0, 0)])
    current_food_idx = 0
    score = 0
    steps = 0

    for move in moves:
        head_row, head_col = snake[0]
        if move == 'U':
            new_row, new_col = head_row - 1, head_col
        elif move == 'D':
            new_row, new_col = head_row + 1, head_col
        elif move == 'L':
            new_row, new_col = head_row, head_col - 1
        else:  # 'R'
            new_row, new_col = head_row, head_col + 1

        new_head = (new_row, new_col)

        # Step 1: Check if new head is out of bounds
        if not (0 <= new_row < height) or not (0 <= new_col < width):
            break

        # Step 2: Check if new head is current food
        is_eating = current_food_idx < len(food) and new_head == food[current_food_idx]

        if is_eating:
            snake.appendleft(new_head)
            score += 1
            current_food_idx += 1
        else:
            # Remove tail
            snake.pop()
            snake.appendleft(new_head)

        # Step 3: Check collision with the rest of the snake
        if any(segment == new_head for segment in snake[1:]):
            break

        steps += 1

    return (score, steps)

