def realize_gains(trades, method):
    if method not in ('fifo', 'lifo'):
        raise ValueError
    lots = []
    total_gain = 0
    for trade in trades:
        try:
            kind, qty, price = trade
        except (ValueError, TypeError):
            raise ValueError
        if type(qty) is not int or type(price) is not int:
            raise ValueError
        if qty < 1:
            raise ValueError
        if price < 0:
            raise ValueError
        if kind == 'buy':
            lots.append((qty, price))
        elif kind == 'sell':
            remaining = qty
            if method == 'fifo':
                index = 0
                while remaining > 0 and index < len(lots):
                    current_qty, current_price = lots[index]
                    take = min(remaining, current_qty)
                    total_gain += take * (price - current_price)
                    remaining -= take
                    new_qty = current_qty - take
                    if new_qty == 0:
                        del lots[index]
                    else:
                        lots[index] = (new_qty, current_price)
                        index += 1
            elif method == 'lifo':
                index = len(lots) - 1
                while remaining > 0 and index >= 0:
                    current_qty, current_price = lots[index]
                    take = min(remaining, current_qty)
                    total_gain += take * (price - current_price)
                    remaining -= take
                    new_qty = current_qty - take
                    if new_qty == 0:
                        del lots[index]
                    else:
                        lots[index] = (new_qty, current_price)
                    index -= 1
            if remaining > 0:
                raise ValueError
    return (total_gain, lots)

