def min_jumps(lengths):
    if not isinstance(lengths, list):
        raise ValueError
    n = len(lengths)
    if n < 1 or n > 10**5:
        raise ValueError
    for num in lengths:
        if not isinstance(num, int) or isinstance(num, bool):
            raise ValueError
        if num < 0:
            raise ValueError
    if n == 1:
        return 0
    jumps = 0
    current_end = 0
    farthest = 0
    for i in range(n):
        if i <= current_end:
            farthest = max(farthest, i + lengths[i])
        if i == current_end:
            jumps += 1
            current_end = farthest
            if current_end >= n - 1:
                break
    return jumps if current_end >= n - 1 else -1

