import re
from collections import defaultdict
from fractions import Fraction

def dice_counts(spec):
    if not isinstance(spec, str):
        raise ValueError
    terms = spec.split('+')
    if len(terms) < 1 or len(terms) > 10:
        raise ValueError
    for term in terms:
        if not term:
            raise ValueError
    total_dice = 0
    dice_list = []
    constant_sum = 0
    for term in terms:
        if 'd' in term:
            parts = term.split('d')
            if len(parts) != 2:
                raise ValueError
            n_part, s_part = parts[0], parts[1]
            if not (n_part.isdigit() and s_part.isdigit()):
                raise ValueError
            if (n_part != '0' and n_part[0] == '0') or (s_part != '0' and s_part[0] == '0'):
                raise ValueError
            N = int(n_part)
            S = int(s_part)
            if N < 1 or N > 20 or S < 2 or S > 100:
                raise ValueError
            total_dice += N
            if total_dice > 20:
                raise ValueError
            for _ in range(N):
                dice_list.append(S)
        else:
            if not term.isdigit():
                raise ValueError
            if term != '0' and term[0] == '0':
                raise ValueError
            value = int(term)
            if value < 0 or value > 1000:
                raise ValueError
            constant_sum += value
    distribution = {0: 1}
    for S in dice_list:
        new_distribution = defaultdict(int)
        for current_sum, count in distribution.items():
            for die_value in range(1, S + 1):
                new_sum = current_sum + die_value
                new_distribution[new_sum] += count
        distribution = dict(new_distribution)
    final_distribution = defaultdict(int)
    for total, count in distribution.items():
        new_total = total + constant_sum
        final_distribution[new_total] += count
    return final_distribution

def chance_at_least(spec, target):
    if not isinstance(target, int):
        raise ValueError
    dist = dice_counts(spec)
    total_outcomes = sum(dist.values())
    favorable = 0
    for total, count in dist.items():
        if total >= target:
            favorable += count
    return Fraction(favorable, total_outcomes)

